function mk(over) {
  const o = { ...BASE, ...over };
  return ['--a', o.a, '--b', o.b, '--c', o.c, '--d', o.d, '--e', o.e, '--f', o.f, '--g', o.g];
}
const C = (n) => String.fromCharCode(n);

// C0 separators: str.isspace() is True for these, but int() may reject them.
const SEPS = [0x1c, 0x1d, 0x1e, 0x1f].map(C);
// Real ASCII whitespace int() accepts.
const OK_WS = [0x09, 0x0a, 0x0d, 0x0b, 0x0c, 0x20].map(C);
// Non-ASCII whitespace int() accepts.
const UNI_WS = [0x00a0, 0x3000, 0x2028, 0x2029, 0x0085, 0x1680, 0x2000, 0x2009,
  0x200a, 0x202f, 0x205f].map(C);

const INT2 = [];
for (const s of SEPS) {
  INT2.push(s + '5', '5' + s, s + '5' + s, s + s + '5', s + '٥', '٥' + s,
    s + '+5', s + '١٢٣', s + '５', '5' + s + '5', s);
}
for (const w of OK_WS) INT2.push(w + '5', '5' + w, w + '٥' + w);
for (const w of UNI_WS) INT2.push(w + '5', '5' + w, w + '٥' + w, w + '٥' + C(0x1c));
// separator mixed with real whitespace
INT2.push(' ' + C(0x1c) + '5', C(0x1c) + ' 5', '5' + C(0x1c) + ' ',
  ' ' + C(0x1c) + '5', C(0x1f) + '　' + '5');
// further Unicode decimal-digit blocks
INT2.push('༥', '၉', '៥', '᠕', '᥋', '᧕',
  '꘥', '꣕', '꤅', '꧕', '꧵', '꩕', '꯵',
  '᱅', '᱕', '᭕', '᮵', '᪅', '᪕', '௥',
  '௦', '⁰', '༪', '߅', '၁၂');
INT2.push('\u{11c55}', '\u{11d55}', '\u{11da5}', '\u{118e5}', '\u{11955}', '\u{11735}',
  '\u{16a65}', '\u{16ac5}', '\u{1e145}', '\u{1e2f5}', '\u{1e4f5}', '\u{1fbf5}',
  '\u{10d35}', '\u{11066}\u{11067}', '\u{1e955}');

const NEG2 = [
  '-٥٥', '-１.２', '-٥١', '-\u{1d7d8}', '-\u{1fbf5}',
  '-๐', '-０.５', '-٥.', '-.٥٥', '-०१२',
  '-۵', '-০', '-૦', '-\u{104a0}', '-\u{16b50}',
];
// Tokens that should be option-like on BOTH sides (parity guard).
const NOTNEG = [
  '-é', '- 5', '-5é', '-​5', '-﻿5', '-٥ ', '- ٥',
  '-٥ ', '-−٥', '-٥_٥', '--٥', '-٥' + C(0x1c),
];

const TEXT2 = [
  // ZWJ sequences with skin tones
  '\u{1f469}\u{1f3fc}‍❤️‍\u{1f48b}‍\u{1f468}\u{1f3ff}',
  '\u{1f9d1}‍\u{1f91d}‍\u{1f9d1}', '\u{1f46b}\u{1f3fd}',
  '\u{1f3c3}\u{1f3fe}‍♀️', '\u{1f6b5}\u{1f3fb}‍♂️',
  '\u{1f3f4}\u{e0067}\u{e0062}\u{e0077}\u{e006c}\u{e0073}\u{e007f}',
  // BOM leading
  '﻿\u{1f600}', '﻿́', '﻿-٥', '﻿ ', '﻿﻿﻿',
  // boundary code points
  C(0x7f), C(0x80), '߿ࠀ', 'ࠀ߿',
  '￿\u{10000}', '\u{10000}￿', '\u{10ffff}\u{10ffff}',
  C(0x1c) + C(0x1d) + C(0x1e) + C(0x1f), C(0x1b) + '[31m', C(0x0b) + C(0x0c),
  C(0x01) + C(0x02) + C(0x03), C(0x7f) + '', ' ',
  // combining marks
  'กั้', 'निं', '각한ㄱ',
  'אַּש', 'اَللٰه',
  'ẚ̣̇', 'Å̧̨',
  '\u{1f600}', '\ud83d', '\ude00', '\u{10000}',
  '\u{1d7ce}\u{1d7cf}', '\u{1fbf0}\u{1fbf9}',
  "'\u{1f600}", '"\u{1f600}', '\'"é', '\\é', 'é\\\'"',
  '中'.repeat(60), 'ÿ'.repeat(60), '\u{1f600}'.repeat(30),
];

const DEC2 = [];
for (const s of SEPS) DEC2.push('28' + s, s + '28', '28' + s + s, '2' + s + '8');
for (const w of UNI_WS) DEC2.push('28' + w + C(0x1c), '28' + C(0x1c) + w);
DEC2.push('​', '28​ ', ' 28​',
  '٥', '２８', '\u{1f600}28', '28\u{1f600}',
  '﻿ ', ' ﻿', 'Z ', 'Z​',
  '28' + C(0x0b) + C(0x0c), C(0x0b) + '28');

export function buildCases2() {
  const cases = [];
  for (const v of INT2) cases.push(mk({ f: v, g: v }));
  for (const v of INT2.slice(0, 26)) { cases.push(mk({ f: v })); cases.push(mk({ g: v })); }
  for (const v of NEG2) { cases.push(mk({ a: v })); cases.push(mk({ c: v })); }
  for (const v of NOTNEG) cases.push(mk({ a: v }));
  for (const t of TEXT2) cases.push(mk({ a: t, c: t, d: t }));
  for (const v of DEC2) cases.push(mk({ b: v, e: v }));
  cases.push(['--a', 'x', '--b', '28', '--c', 'x', '--d', 'y', '--e', '28', '--f=-٠', '--g', '1']);
  cases.push(['--a', 'x', '--b', '28', '--c', 'x', '--d', 'y', '--e', '28', '--f', '-0', '--g=-０']);
  cases.push(['--a=-٥', '--b', '28', '--c', 'x', '--d', 'y', '--e', '28', '--f', '1', '--g', '1']);
  return cases;
}

